# ============================================================
# 二、报告拼装引擎（输出格式与电脑版一致；纯 Python，无 Kivy 依赖）
# ============================================================


def build_report_header(date_str):
    lines = [
        "违法违规情形法律依据查询报告",
        "生成日期：" + date_str,
        "",
        "情形清单",
    ]
    for i, k in enumerate(SIT_ORDER, 1):
        lines.append("%d. %s" % (i, SIT_NAMES[k]))
    return lines


def build_report_body(key):
    parts = []
    for head, idx in BLOCKS[key]:
        body = CHUNKS[idx]
        if "{NAME}" in body:
            body = body.replace("{NAME}", SIT_NAMES[key])
        if head == "__info__":
            parts.append(body)
        else:
            parts.append(head)
            parts.append(body)
        parts.append("")
    return parts


def build_report_text(key, date_str):
    lines = build_report_header(date_str)
    lines.append("")
    lines.extend(build_report_body(key))
    return "\n".join(lines)

# ============================================================
# 三、关键词检索（内置报告库 + laws.csv 法规库）
# ============================================================
CSV_DATA = []
CSV_HEADERS = []


def clean_html(text):
    if not text:
        return ""
    text = re.sub(r'<[^>]+>', '', text)
    return text.replace('&nbsp;', ' ').strip()


def split_into_segments(text):
    if not text:
        return []
    pattern = re.compile(r'第[零一二三四五六七八九十百千万\d]+条')
    starts = [m.start() for m in pattern.finditer(text)]
    if not starts:
        return [text]
    segments = []
    if starts[0] > 0:
        segments.append(text[:starts[0]])
    for i in range(len(starts)):
        end = starts[i + 1] if i + 1 < len(starts) else len(text)
        segments.append(text[starts[i]:end])
    return segments


def load_bundled_csv():
    """加载 law.csv / laws.csv（有则用，无则只用内置报告库）"""
    for fname in ("laws.csv", "law.csv"):
        target = fname
        if not os.path.exists(target):
            found = resource_find(fname)
            if found:
                target = found
            else:
                target = os.path.join(os.path.dirname(os.path.abspath(__file__)), fname)
        if not os.path.exists(target):
            continue
        for enc in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                with open(target, 'r', encoding=enc, errors='ignore') as f:
                    reader = csv.DictReader(f)
                    if not reader.fieldnames:
                        continue
                    CSV_HEADERS.clear()
                    CSV_HEADERS.extend([h.strip() for h in reader.fieldnames])
                    CSV_DATA.clear()
                    for row in reader:
                        clean_row = {k.strip(): clean_html(v) for k, v in row.items() if k and v}
                        if clean_row:
                            CSV_DATA.append(clean_row)
                    return len(CSV_DATA), fname
            except Exception:
                continue
    return 0, "未找到法规 CSV"


def search_all_text(keyword):
    kw = keyword.strip()
    if not kw:
        return "请输入关键词。"

    blocks = []

    # 1) 内置报告库（情形全文）
    for k in SIT_ORDER:
        body = "\n".join(build_report_body(k))
        if kw not in body:
            continue
        hits = []
        for line in body.split("\n"):
            if kw in line:
                line = line.strip()
                if line and line not in hits:
                    hits.append(line)
        if hits:
            blocks.append("【情形】%s\n%s" % (SIT_NAMES[k], "\n".join("  · " + h for h in hits[:10])))

    # 2) 法规库 CSV
    for row in CSV_DATA:
        row_text = "".join([str(v) for v in row.values()])
        if kw in row_text:
            text = ""
            for field in ("序号", "名称", "发布日期", "文号", "网址"):
                if row.get(field):
                    text += "%s：%s\n" % (field, row[field])
            for key, val in row.items():
                if key in ("序号", "名称", "发布日期", "文号", "网址") or not val:
                    continue
                if kw in val and len(val) > 50:
                    segs = [s.strip() for s in split_into_segments(val) if kw in s]
                    if segs:
                        text += "%s：\n%s\n" % (key, "\n".join("  " + s for s in segs))
                    else:
                        text += "%s：%s\n" % (key, val)
                else:
                    text += "%s：%s\n" % (key, val)
            blocks.append("【法规库】\n" + text.strip())

    if not blocks:
        return "未找到包含「%s」的内容。" % kw

    return "【搜索关键词】%s（共匹配 %d 条）\n\n%s" % (
        kw, len(blocks), "\n\n".join(blocks[:30]))


# ============================================================
# 四、界面
# ============================================================
class MainScreen(BoxLayout):
    def __init__(self, **kwargs):
        super().__init__(orientation="vertical", padding=dp(8), spacing=dp(6), **kwargs)

        self.add_widget(Label(
            text="[b]规划土地执法法律依据查询[/b]", markup=True,
            size_hint_y=None, height=dp(34), font_size=dp(17),
            color=(0, 0, 0, 1)))

        row1 = BoxLayout(size_hint_y=None, height=dp(46), spacing=dp(6))
        row1.add_widget(Label(text="情形：", size_hint_x=None, width=dp(46),
                              color=(0, 0, 0, 1)))
        vals = []
        self.key_by_label = {}
        for i, k in enumerate(SIT_ORDER, 1):
            short = SIT_NAMES[k]
            if len(short) > 14:
                short = short[:14] + "…"
            label = "%d｜%s" % (i, short)
            vals.append(label)
            self.key_by_label[label] = k
        self.spinner = Spinner(text=vals[0], values=vals, size_hint_x=1,
                               background_color=(0.82, 0.82, 0.82, 1),
                               color=(0, 0, 0, 1), font_size=dp(13))
        row1.add_widget(self.spinner)
        self.add_widget(row1)

        row2 = BoxLayout(size_hint_y=None, height=dp(44), spacing=dp(6))
        self.search_input = TextInput(
            hint_text="搜法条或政策（如：搭建 / 第八十条）", multiline=False,
            foreground_color=(0, 0, 0, 1), background_color=(1, 1, 1, 1),
            font_size=dp(13))
        btn_search = Button(text="搜索", size_hint_x=None, width=dp(64),
                            background_color=(0.2, 0.6, 1, 1), font_size=dp(13))
        btn_search.bind(on_release=self.on_search)
        row2.add_widget(self.search_input)
        row2.add_widget(btn_search)
        self.add_widget(row2)

        row3 = BoxLayout(size_hint_y=None, height=dp(46), spacing=dp(6))
        b1 = Button(text="查询该情形（完整报告）", background_color=(0.2, 0.7, 0.2, 1),
                    font_size=dp(13))
        b1.bind(on_release=self.on_query_situation)
        b2 = Button(text="复制全部", size_hint_x=None, width=dp(88),
                    background_color=(0.85, 0.55, 0.2, 1), font_size=dp(13))
        b2.bind(on_release=self.on_copy_result)
        row3.add_widget(b1)
        row3.add_widget(b2)
        self.add_widget(row3)

        self.result_display = TextInput(
            text="正在初始化数据...",
            readonly=True,
            multiline=True,
            foreground_color=(0, 0, 0, 1),
            background_color=(1, 1, 1, 1),
            font_size=dp(12.5),
            size_hint=(1, 1),
        )
        self.add_widget(self.result_display)

    # ---------- 事件 ----------
    def current_key(self):
        sel = self.spinner.text
        if sel in self.key_by_label:
            return self.key_by_label[sel]
        if "｜" in sel:
            k = sel.split("｜", 1)[0].strip()
            if k in SIT_NAMES:
                return k
        return SIT_ORDER[0]

    def on_query_situation(self, *args):
        key = self.current_key()
        date_str = datetime.now().strftime("%Y年%m月%d日 %H:%M")
        self.result_display.text = build_report_text(key, date_str)
        self.result_display.cursor = (0, 0)

    def on_search(self, *args):
        kw = self.search_input.text.strip()
        if not kw:
            return
        self.result_display.text = search_all_text(kw)
        self.result_display.cursor = (0, 0)

    def on_copy_result(self, *args):
        Clipboard.copy(self.result_display.text)


class LawApp(App):
    def build(self):
        Window.clearcolor = (0.96, 0.96, 0.96, 1)

        def init_load(dt):
            count, status = load_bundled_csv()
            tip = "已内置 %d 项情形的完整法律依据报告（与电脑版输出一致）。" % len(SIT_ORDER)
            if count:
                tip += "\n法规库：%s，共 %d 条。" % (status, count)
            else:
                tip += "\n未检测到法规 CSV，关键词搜索仅在内置报告库中进行。"
            tip += "\n\n请选择情形后点击「查询该情形（完整报告）」。"
            self.root.result_display.text = tip

        Clock.schedule_once(init_load, 0.2)
        return MainScreen()


if __name__ == "__main__":
    LawApp().run()
